insert into public.news (slug_es,slug_en,title_es,title_en,excerpt_es,excerpt_en,content_es,content_en,image,category,source_name,source_url,published_at,published,featured) values ('dualsense','dualsense','PlayStation presenta el DualSense de edición limitada de GTA VI','PlayStation reveals limited-edition GTA VI DualSense','PlayStation ha presentado un mando DualSense de edición limitada inspirado en GTA VI. Es uno de los productos oficiales más destacados aparecidos durante la campaña previa al lanzamiento.','PlayStation has revealed a limited-edition DualSense inspired by GTA VI, adding another major official product to the game&#x27;s pre-launch campaign.','<p>PlayStation ha presentado un mando DualSense de edición limitada inspirado en GTA VI. Es uno de los productos oficiales más destacados aparecidos durante la campaña previa al lanzamiento. La información oficial de Rockstar sitúa el lanzamiento el 19 de noviembre de 2026.</p><p>Fuente: Rockstar Games y fuentes especializadas</p>','<p>PlayStation has revealed a limited-edition DualSense inspired by GTA VI, adding another major official product to the game&#x27;s pre-launch campaign. Rockstar officially lists November 19, 2026 as the release date.</p><p>Source: Rockstar Games and specialist outlets</p>','/assets/images/Jason_Duval_08.jpg','GTA VI','Rockstar Games y medios especializados',null,'2026-09-03T10:00:00+02:00',true,false) on conflict (slug_es) do update set title_es=excluded.title_es,title_en=excluded.title_en,excerpt_es=excluded.excerpt_es,excerpt_en=excluded.excerpt_en,content_es=excluded.content_es,content_en=excluded.content_en,image=excluded.image,published_at=excluded.published_at,published=true;
insert into public.news (slug_es,slug_en,title_es,title_en,excerpt_es,excerpt_en,content_es,content_en,image,category,source_name,source_url,published_at,published,featured) values ('extended-look','extended-look','GTA VI: el Extended Look muestra por primera vez una gran parte del gameplay','GTA VI Extended Look reveals a huge amount of new gameplay','Rockstar ha publicado un Extended Look de GTA VI capturado íntegramente en PlayStation 5. El vídeo ofrece nuevas escenas de Vice City y Leonida, combate, conducción, actividades y una visión mucho más amplia del mundo del juego.','Rockstar has released the GTA VI Extended Look, captured entirely on PlayStation 5. It shows new Vice City and Leonida scenes, combat, driving, activities and a much broader look at the world.','<p>Rockstar ha publicado un Extended Look de GTA VI capturado íntegramente en PlayStation 5. El vídeo ofrece nuevas escenas de Vice City y Leonida, combate, conducción, actividades y una visión mucho más amplia del mundo del juego. La información oficial de Rockstar sitúa el lanzamiento el 19 de noviembre de 2026.</p><p>Fuente: Rockstar Games y fuentes especializadas</p>','<p>Rockstar has released the GTA VI Extended Look, captured entirely on PlayStation 5. It shows new Vice City and Leonida scenes, combat, driving, activities and a much broader look at the world. Rockstar officially lists November 19, 2026 as the release date.</p><p>Source: Rockstar Games and specialist outlets</p>','/assets/images/Jason_and_Lucia_12.jpg','GTA VI','Rockstar Games y medios especializados',null,'2026-08-27T10:00:00+02:00',true,false) on conflict (slug_es) do update set title_es=excluded.title_es,title_en=excluded.title_en,excerpt_es=excluded.excerpt_es,excerpt_en=excluded.excerpt_en,content_es=excluded.content_es,content_en=excluded.content_en,image=excluded.image,published_at=excluded.published_at,published=true;
insert into public.news (slug_es,slug_en,title_es,title_en,excerpt_es,excerpt_en,content_es,content_en,image,category,source_name,source_url,published_at,published,featured) values ('netflix','netflix','El Extended Look de GTA VI supera los 31 millones de espectadores en Netflix','GTA VI Extended Look passes 31 million Netflix viewers','El estreno especial del Extended Look en Netflix tuvo un enorme impacto: según datos publicados esta semana, el vídeo superó los 31 millones de espectadores y encabezó las listas de Netflix durante la semana de su estreno.','The special Netflix debut of the GTA VI Extended Look generated huge attention. Published figures put the video above 31 million viewers and at the top of Netflix&#x27;s weekly chart during its launch week.','<p>El estreno especial del Extended Look en Netflix tuvo un enorme impacto: según datos publicados esta semana, el vídeo superó los 31 millones de espectadores y encabezó las listas de Netflix durante la semana de su estreno. La información oficial de Rockstar sitúa el lanzamiento el 19 de noviembre de 2026.</p><p>Fuente: Rockstar Games y fuentes especializadas</p>','<p>The special Netflix debut of the GTA VI Extended Look generated huge attention. Published figures put the video above 31 million viewers and at the top of Netflix&#x27;s weekly chart during its launch week. Rockstar officially lists November 19, 2026 as the release date.</p><p>Source: Rockstar Games and specialist outlets</p>','/assets/images/Vice_City_10.jpg','GTA VI','Rockstar Games y medios especializados',null,'2026-09-01T10:00:00+02:00',true,false) on conflict (slug_es) do update set title_es=excluded.title_es,title_en=excluded.title_en,excerpt_es=excluded.excerpt_es,excerpt_en=excluded.excerpt_en,content_es=excluded.content_es,content_en=excluded.content_en,image=excluded.image,published_at=excluded.published_at,published=true;